package io.ledgerflow.ledger.domain.event;

import java.time.Instant;
import java.util.List;
import java.util.UUID;

/** Past tense: this states a fact that has already happened. */
public record FundsHeld(UUID holdId, UUID accountId, List<String> wallets, Instant expiresAt) {}

package io.ledgerflow.ledger.adapter.out.messaging;

import io.ledgerflow.ledger.domain.event.FundsHeld;
import org.springframework.kafka.core.KafkaTemplate;
import org.springframework.stereotype.Component;

@Component
public class HoldEventPublisher {

    static final String TOPIC = "wallet-hold-events";

    private final KafkaTemplate<String, Object> kafka;

    HoldEventPublisher(KafkaTemplate<String, Object> kafka) { this.kafka = kafka; }

    public void publish(FundsHeld event) {
        kafka.send(TOPIC, event.holdId().toString(), event);
    }
}

// adapter/in/web/HoldController.java
@PostMapping
@ResponseStatus(HttpStatus.CREATED)
List<FundsHold> place(@Valid @RequestBody HoldRequest req) {
    var holds = placeHold.place(req.accountId(), req.wallets());   // transaction commits here

    // ...and only then do we publish. Two systems, two writes, no atomicity.
    // This is a real bug. Step 10 reproduces it and fixes it. Leave it for now.
    publisher.publish(new FundsHeld(
            holds.getFirst().id(), req.accountId(), req.wallets(), holds.getFirst().expiresAt()));

    return holds;
}

package io.ledgerflow.notification.adapter.in.messaging;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.kafka.annotation.KafkaListener;
import org.springframework.stereotype.Component;

import java.time.Instant;
import java.util.List;
import java.util.UUID;

@Component
class FundsHoldListener {

    private static final Logger log = LoggerFactory.getLogger(FundsHoldListener.class);

    record FundsHeld(UUID holdId, UUID accountId, List<String> wallets, Instant expiresAt) {}

    @KafkaListener(topics = "wallet-hold-events")
    void onFundsHeld(FundsHeld event) {
        log.info("would email the customer about hold {} ({} wallets)",
                 event.holdId(), event.wallets().size());
    }
}
